      [email, password],
    );
    uid = user.rows[0].id;
    await db.query("insert into profiles (id, role, name) values ($1, 'client', $2)", [uid, name]);
    await db.query("select accept_invite($1, $2, $3)", [code, uid, name]);
    await db.query("commit");
